const string W="D:/project/MTGB/design-demos/battlefield-redesign-2026-10-24/";
var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>();
var f=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
var rows=new System.Collections.Generic.List<object>();int checks=0,failed=0;
void Check(bool pass,string context){checks++;if(!pass)failed++;rows.Add(new{pass,context});}
ForgeSeatView Read(string key)=>JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(W+"action-ui-inputs/"+key+".json"));
Rect Bounds(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c.Min(p=>p.x),c.Min(p=>p.y),c.Max(p=>p.x),c.Max(p=>p.y));}
System.Collections.IEnumerator Settle(){yield return new WaitForSecondsRealtime(.6f);Canvas.ForceUpdateCanvases();}
void Save(string status){var json=System.Type.GetType("Newtonsoft.Json.JsonConvert, Newtonsoft.Json").GetMethod("SerializeObject",new[]{typeof(object)});System.IO.File.WriteAllText(W+"unity-redesign-interactions.json",(string)json.Invoke(null,new object[]{new{status,checks,failed,rows}}));}
bool Click(UnityEngine.UI.Button b){var r=Bounds((RectTransform)b.transform);var p=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=new Vector2((r.xMin+r.xMax)*.5f,(Mathf.Max(0,r.yMin)+Mathf.Min(Screen.height,r.yMax))*.5f),button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(p,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()!=b){rows.Add(new{blocked=b.name,hits=hits.Take(3).Select(h=>h.gameObject.name).ToArray()});return false;}UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,UnityEngine.EventSystems.ExecuteEvents.pointerDownHandler);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,UnityEngine.EventSystems.ExecuteEvents.pointerUpHandler);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);return true;}
var editorAssembly=typeof(UnityEditor.Editor).Assembly;var gameViewType=editorAssembly.GetType("UnityEditor.GameView");var gameView=UnityEditor.EditorWindow.GetWindow(gameViewType);var selectedSize=gameViewType.GetProperty("selectedSizeIndex",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);int savedIndex=(int)selectedSize.GetValue(gameView);var sizesType=editorAssembly.GetType("UnityEditor.GameViewSizes");var sizes=typeof(UnityEditor.ScriptableSingleton<>).MakeGenericType(sizesType).GetProperty("instance").GetValue(null);var group=sizesType.GetMethod("GetGroup").Invoke(sizes,new object[]{Enum.Parse(editorAssembly.GetType("UnityEditor.GameViewSizeGroupType"),"Standalone")});var customIndices=new System.Collections.Generic.List<int>();string savedLanguage=GamePreferences.Language;float savedScale=GamePreferences.TextScale;
void Resize(int w,int h){var texts=(string[])group.GetType().GetMethod("GetDisplayTexts").Invoke(group,null);int index=texts.Length;var size=Activator.CreateInstance(editorAssembly.GetType("UnityEditor.GameViewSize"),new object[]{Enum.Parse(editorAssembly.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),w,h,"MTGB copied-scene validation"});group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{size});customIndices.Add(index);selectedSize.SetValue(gameView,index);gameView.Repaint();}
void Restore(){selectedSize.SetValue(gameView,savedIndex);foreach(int i in customIndices.OrderByDescending(i=>i))group.GetType().GetMethod("RemoveCustomSize").Invoke(group,new object[]{i});GamePreferences.SetLanguage(savedLanguage);GamePreferences.SetScale(savedScale);}
System.Collections.IEnumerator Run(){
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1024,768)}){
  Resize(size.x,size.y);yield return Settle();
  foreach(string language in new[]{"zh-CN","en-US","ja-JP"}){
   GamePreferences.SetLanguage(language);yield return null;while(!GamePreferences.Ready)yield return null;GamePreferences.SetScale(1.3f);
   foreach(string key in new[]{"priority","hand","manual-number","phyrexian","undo"}){
    ui.Present(null,1,false,null,null,"");yield return null;var v=Read(key);ui.Present(v,v.seat,true,_=>{},null,"");yield return Settle();
    var canvas=GameObject.Find("Canvas").transform;var mode=Bounds((RectTransform)canvas.Find("PriorityControlMode"));Check(Screen.width==size.x&&Screen.height==size.y,"actual render size "+size);Check(mode.yMin>=0&&mode.yMin<14,"bottom anchor "+size+"/"+language+"/"+key);
    var pool=canvas.Find("ManaPoolChips") as RectTransform;var hand=canvas.Find("PlayerHandRoot") as RectTransform;var handBounds=Bounds(hand);
    var upper=canvas.Find("PublicManaPool") as RectTransform;var stack=canvas.Find("StackColumn");if(upper.gameObject.activeSelf&&stack.gameObject.activeSelf){var upperBounds=Bounds(upper);var stackBounds=Bounds((RectTransform)stack);Check(upperBounds.xMax+36*upper.lossyScale.x<stackBounds.xMin,"upper mana clears stack "+size+"/"+language+"/"+key);}
    if(pool.gameObject.activeSelf){var mana=Bounds(pool);Check(mana.xMin>handBounds.xMax,"mana horizontal reserve "+size+"/"+language+"/"+key);var withArrows=Rect.MinMaxRect(mana.xMin-36*pool.lossyScale.x,mana.yMin,mana.xMax+36*pool.lossyScale.x,mana.yMax);var cards=(System.Collections.IDictionary)typeof(ForgeBattlefieldController).GetField("arenaCards",f).GetValue(ui);foreach(System.Collections.DictionaryEntry entry in cards){if(!entry.Key.ToString().StartsWith("Your"))continue;var card=(RectTransform)entry.Value.GetType().GetField("root").GetValue(entry.Value);if(!card.gameObject.activeInHierarchy)continue;var visible=Bounds(card);var lane=card.GetComponentInParent<BattlefieldHorizontalScroll>();if(lane!=null){var clip=Bounds(lane.viewport);visible=Rect.MinMaxRect(Mathf.Max(visible.xMin,clip.xMin),Mathf.Max(visible.yMin,clip.yMin),Mathf.Min(visible.xMax,clip.xMax),Mathf.Min(visible.yMax,clip.yMax));if(visible.width<=0||visible.height<=0)continue;}Check(!withArrows.Overlaps(visible),"mana clears field "+size+"/"+language+"/"+key+"/"+entry.Key);}}
    foreach(var b in canvas.Find("CornerCluster/ControlRow").GetComponentsInChildren<UnityEngine.UI.Button>(false).Where(b=>b.interactable)){var rect=Bounds((RectTransform)b.transform);Check(rect.xMin>=0&&rect.yMin>=0&&rect.xMax<=Screen.width+1&&rect.yMax<=Screen.height+1,"button bounds "+size+"/"+language+"/"+key+"/"+b.name);}
   }
   if(language=="zh-CN"){ui.Present(Read("priority"),1,false,null,null,"");yield return Settle();ScreenCapture.CaptureScreenshot(W+"unity-size-"+size.x+"x"+size.y+".png");yield return new WaitForEndOfFrame();}Save("RUNNING");
  }
 }
 selectedSize.SetValue(gameView,savedIndex);GamePreferences.SetLanguage("zh-CN");yield return null;while(!GamePreferences.Ready)yield return null;GamePreferences.SetScale(1);yield return Settle();
 foreach(var pair in new[]{("priority","SkipCombatButton","ok"),("payment","AutoPayment","ok"),("number","ConfirmValue","confirm-number"),("undo","UndoMana","cancel"),("target","CancelTargetChoice","cancel")}){
  var v=Read(pair.Item1);int calls=0,last=-1;ui.Present(null,1,false,null,null,"");yield return null;ui.Present(v,v.seat,true,i=>{calls++;last=i;},null,"");yield return Settle();var b=GameObject.Find(pair.Item2).GetComponent<UnityEngine.UI.Button>();Check(Click(b)&&calls==1&&last==Array.FindIndex(v.request.options,o=>o.id==pair.Item3),"exact native option "+pair.Item1+"/"+pair.Item3);ui.TrySubmitPresentedOption(last,v.request.requestId);Check(calls==1,"duplicate submit "+pair.Item1);
 }
 var discard=Read("hand");int discardCalls=0;ui.Present(null,1,false,null,null,"");yield return null;ui.Present(discard,discard.seat,true,_=>discardCalls++,null,"");yield return Settle();typeof(ForgeBattlefieldController).GetMethod("SetRedesignHandExpanded",f).Invoke(ui,new object[]{false});var handRoot=GameObject.Find("PlayerHandRoot").transform;var handButton=handRoot.GetComponentsInChildren<UnityEngine.UI.Button>(false).First(b=>b.name.StartsWith("Card_")&&discard.request.options.Any(o=>!o.disabled&&b.name=="Card_"+o.card?.id));Check(Click(handButton)&&discardCalls==0,"first tucked click reveals without submitting");yield return Settle();Check(Click(handButton)&&discardCalls==1,"second hand click submits native selection");
 var source=Read("priority");var own=source.players.First(p=>p.seat==1);var original=own.hand[0];ForgeCardView Copy(string zone,int id){var c=JsonUtility.FromJson<ForgeCardView>(JsonUtility.ToJson(original));c.id=id;c.zone=zone;return c;}source.playableGraveyard=new[]{Copy("Graveyard",81001)};source.playableExile=new[]{Copy("Exile",81002)};source.playableCommand=new[]{Copy("Command",81003)};source.request.options=source.request.options.Concat(source.playableGraveyard.Concat(source.playableExile).Concat(source.playableCommand).Select(c=>new ForgeOption{id="card:"+c.id,label=c.name})).ToArray();int sourceCalls=0;ui.Present(null,1,false,null,null,"");yield return null;ui.Present(source,1,true,_=>sourceCalls++,null,"");yield return Settle();
 foreach(string zone in new[]{"Graveyard","Exile","Command","Hand"}){var b=GameObject.Find("Source_"+zone).GetComponent<UnityEngine.UI.Button>();Check(Click(b),"source tab reachable "+zone);yield return Settle();var ids=GameObject.Find("PlayerHandRoot").GetComponentsInChildren<UnityEngine.UI.Button>(false).Where(x=>x.name.StartsWith("Card_")).Select(x=>x.name).ToArray();Check(zone=="Hand"?ids.Length==own.hand.Length:ids.Length==1&&ids[0]=="Card_"+(zone=="Graveyard"?81001:zone=="Exile"?81002:81003),"source identity "+zone);Check(sourceCalls==0,"source switch does not submit "+zone);}
 Restore();yield return null;while(!GamePreferences.Ready)yield return null;ui.Present(null,1,false,null,null,"");yield return null;ui.Present(Read("priority"),1,false,null,null,"副本 · 只读布局预览");typeof(ForgeBattlefieldController).GetMethod("SetRedesignHandExpanded",f).Invoke(ui,new object[]{true});yield return Settle();ScreenCapture.CaptureScreenshot(W+"unity-redesign-final.png");yield return new WaitForEndOfFrame();Save("COMPLETE");
}
System.Collections.IEnumerator Guard(){var it=Run();for(int frame=0;frame<100000;frame++){bool next=false;object value=null;try{next=it.MoveNext();if(next)value=it.Current;}catch(Exception e){rows.Add(new{exception=e.ToString()});failed++;Restore();Save("ERROR");yield break;}if(!next)break;yield return value;}}
Save("STARTING");ui.StartCoroutine(Guard());return "Resize, native callbacks and source switching started";
